        if (!check_region_connectivity_bfs(c)) return false;
    }
    if (!check_region_0_connectivity_full()) return false;

    for (int c1 = 0; c1 <= M_FIXED; ++c1) {
        for (int c2 = c1 + 1; c2 <= M_FIXED; ++c2) {
